def loss_note(x_from, y_from, y_elbow, x_lab, y_lab, text, color):
    out = [f"<path d='M {_n(x_from)},{_n(y_from)} V {_n(y_elbow)} H {_n(x_lab-8)}' fill='none' "
           f"stroke='{color}' stroke-width='1' stroke-dasharray='2 4'/>"]
    out.append(txt(x_lab, y_lab, text[0], 10, color, 600, "start"))
    if len(text) > 1:
        out.append(txt(x_lab, y_lab + 12, text[1], 9.5, color, 400, "start"))
    return "".join(out)
